-- Migration: recreate kv_store in Supabase and load existing Turso data
-- Generated from fingallians-blitz.db (Turso export) on 2026-08-04
-- Revised 2026-08-04: table renamed to match what src/App.jsx actually queries
-- (kv_store, not blitz_kv_store), value column is jsonb (the front end reads/writes
-- plain JS objects via supabase-js, not JSON-encoded text like the old Turso code
-- did), and RLS policies grant the anon role access — the app now talks to Supabase
-- directly from the browser (src/supabaseClient.js) using the anon key, not through
-- a server-side service_role proxy like the original Turso setup.
--
-- Run this once in the Supabase SQL editor for the project whose
-- VITE_SUPABASE_URL / VITE_SUPABASE_ANON_KEY are set in Vercel. Safe to
-- re-run (table creation is idempotent, inserts upsert on conflict).
--
-- If you previously ran the old version of this file, it created a separate
-- table called "blitzA_kv_store" that the app never actually reads from — safe
-- to leave in place (harmless, unused) or drop it once this is confirmed working:
--   drop table if exists blitz_kv_store;

create table if not exists kv_store (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz default now()
);

alter table kv_store enable row level security;

-- The front end uses the anon key directly (no server-side proxy anymore), so
-- anon needs read/write on this table. This intentionally mirrors the app's own
-- access control (admin passcode, club passwords, referee link) rather than the
-- database's — same trust model Supabase's docs assume for this kind of
-- single-page app. Scoped to only this table, nothing else in the project.
drop policy if exists "anon select kv_store" on kv_store;
drop policy if exists "anon insert kv_store" on kv_store;
drop policy if exists "anon update kv_store" on kv_store;

create policy "anon select kv_store" on kv_store
  for select to anon using (true);
create policy "anon insert kv_store" on kv_store
  for insert to anon with check (true);
create policy "anon update kv_store" on kv_store
  for update to anon using (true) with check (true);

-- Load existing data (upsert-safe to re-run)
insert into kv_store (key, value, updated_at) values (
  'announcements',
  $kv_announcements$[]$kv_announcements$::jsonb,
  '2026-07-31 13:27:36'
) on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;

